        { id: 'L4-G6-EX2', lessonId: 'L4', section: 'textbook-practice', type: 'fill-blank', prompt: 'Hoàn thành câu bằng 非…不可.', textWithBlanks: '台北東區有很多有特色的商店，___。', blanks: [{ index: 0, acceptedAnswers: ['你來台北非去逛逛不可'] }], targetPattern: 'L4-G6' },
        { id: 'L4-G6-EX3', lessonId: 'L4', section: 'textbook-practice', type: 'fill-blank', prompt: 'Hoàn thành câu bằng 非…不可.', textWithBlanks: '你的手機月租費太貴了，___。', blanks: [{ index: 0, acceptedAnswers: ['非換一家電信公司不可'] }], targetPattern: 'L4-G6' },
        { id: 'L4-G6-EX4', lessonId: 'L4', section: 'textbook-practice', type: 'fill-blank', prompt: 'Hoàn thành câu bằng 非…不可.', textWithBlanks: '想多了解台灣人傳統的風俗習慣，___。', blanks: [{ index: 0, acceptedAnswers: ['非去台南走一趟不可'] }], targetPattern: 'L4-G6' },
        { id: 'L4-G6-EX5', lessonId: 'L4', section: 'textbook-practice', type: 'fill-blank', prompt: 'Hoàn thành câu bằng 非…不可.', textWithBlanks: '昨天買的外套，裡面破了一個洞，___。', blanks: [{ index: 0, acceptedAnswers: ['我非去退貨不可'] }], targetPattern: 'L4-G6' }
